def retirar(saldo, monto):
    if monto > saldo:
        raise ValueError("Saldo insuficiente")
    return saldo - monto

saldo = 1000
try:
    saldo = retirar(saldo, 5000)
except ValueError as e:
    print(e)
print(saldo)
